<script setup lang="ts">
import { ref } from 'vue';
import { usePage } from '../composables/usePage';
import type { ThemePreference } from '../lib/preferences';
const { t, preferences } = usePage();
const cleared = ref(false);
const zones = [...new Set([preferences.timeZone, 'UTC', 'Asia/Shanghai', 'Asia/Tokyo', 'Asia/Dubai', 'Europe/London', 'Europe/Paris', 'America/New_York', 'America/Los_Angeles', 'Australia/Sydney'])];
</script>
<template><RouterLink class="back-link" to="/profile">← {{ t('profile.title') }}</RouterLink><div class="page-heading"><div><p class="eyebrow">{{ t('settings.eyebrow') }}</p><h1 tabindex="-1">{{ t('settings.title') }}</h1><p class="muted">{{ t('settings.description') }}</p></div></div><section class="settings-panel"><div class="setting-row"><label for="locale"><strong>{{ t('common.language') }}</strong><span>{{ t('settings.languageHint') }}</span></label><select id="locale" :value="preferences.locale" @change="preferences.setLocale(($event.target as HTMLSelectElement).value)"><option value="en-US">English (US)</option><option value="zh-CN">简体中文</option></select></div><div class="setting-row"><label for="theme"><strong>{{ t('settings.theme') }}</strong><span>{{ t('settings.themeHint') }}</span></label><select id="theme" :value="preferences.theme" @change="preferences.setTheme(($event.target as HTMLSelectElement).value as ThemePreference)"><option v-for="item in ['dark', 'light', 'system']" :key="item" :value="item">{{ t('settings.' + item) }}</option></select></div><div class="setting-row"><label for="timezone"><strong>{{ t('settings.timezone') }}</strong><span>{{ t('settings.timezoneHint') }}</span></label><select id="timezone" :value="preferences.timeZone" @change="preferences.setTimeZone(($event.target as HTMLSelectElement).value)"><option v-for="zone in zones" :key="zone" :value="zone">{{ zone }}</option></select></div></section><section class="settings-panel"><h2>{{ t('settings.privacy') }}</h2><p class="muted">{{ t('settings.privacyHint') }}</p><button @click="preferences.clearSaved(); cleared = true">{{ t('settings.clear') }}</button><p v-if="cleared" role="status">{{ t('settings.cleared') }}</p></section><p v-if="preferences.storageUnavailable" class="notice" role="alert">{{ t('settings.storageUnavailable') }}</p><p class="source-note">{{t('world.privacy')}}</p></template>
